fn reputation_proof_json(proof: &ReputationMerkleProofV1) -> Value {
    let mut map = Map::new();
    map.insert("provider_id".into(), Value::from(proof.provider_id.clone()));
    map.insert(
        "leaf_index".into(),
        Value::from(u64::from(proof.leaf_index)),
    );
    map.insert(
        "siblings_hex".into(),
        Value::Array(
            proof
                .siblings
                .iter()
                .map(|sibling| Value::from(hex::encode(sibling)))
                .collect(),
        ),
    );
    Value::Object(map)
}

pub(crate) async fn handle_post_sorafs_provider_advert(
    State(state): State<SharedAppState>,
    body: Bytes,
) -> Response {
    let Some(cache) = state.sorafs_cache.clone() else {
        return feature_disabled("sorafs discovery API is not enabled on this node");
    };

    let telemetry = state.telemetry.clone();

    let advert = match norito::decode_from_bytes::<ProviderAdvertV1>(body.as_ref()) {
        Ok(value) => value,
        Err(err) => {
            warn!(?err, "failed to decode provider advert payload");
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("invalid provider advert payload: {err}"),
            );
        }
    };

    let now = match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(duration) => duration.as_secs(),
        Err(err) => {
            error!(?err, "system clock error while ingesting provider advert");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "system time error while ingesting advert",
            );
        }
    };

    let advert_profile = advert.body.profile_id.clone();
    let advert_provider_id = advert.body.provider_id;

    let mut guard = cache.write().await;
    match guard.ingest(advert, now) {
        Ok(AdvertIngestResult { outcome, warnings }) => {
            if !warnings.is_empty() {
                warn!(
                    ?warnings,
                    "provider advert ingested with downgrade warnings"
                );
                let telemetry = telemetry.clone();
                for warning in &warnings {
                    telemetry.with_metrics(|tel| {
                        tel.inc_torii_sorafs_admission("warn", warning.telemetry_reason())
                    });
                }
            }

            let response = match outcome {
                AdvertIngest::Stored { fingerprint } => {
                    debug!("stored new provider advert");
                    telemetry
                        .with_metrics(|tel| tel.inc_torii_sorafs_admission("accepted", "stored"));
                    advert_ingest_response("stored", &fingerprint, &warnings)
                }
                AdvertIngest::Replaced { fingerprint } => {
                    debug!("replaced provider advert");
                    telemetry
                        .with_metrics(|tel| tel.inc_torii_sorafs_admission("accepted", "replaced"));
                    advert_ingest_response("replaced", &fingerprint, &warnings)
                }
                AdvertIngest::Duplicate { fingerprint } => {
                    debug!("duplicate provider advert ignored");
                    telemetry.with_metrics(|tel| {
                        tel.inc_torii_sorafs_admission("accepted", "duplicate")
                    });
                    advert_ingest_response("duplicate", &fingerprint, &warnings)
                }
            };
            record_range_capability_metrics(&guard, &telemetry);
            response
        }
        Err(err) => {
            warn!(?err, "failed to ingest provider advert");
            let reason = admission_error_reason(&err);
            telemetry.with_metrics(|tel| tel.inc_torii_sorafs_admission("rejected", reason));
            match err {
                AdvertError::UnknownCapabilities { capabilities } => {
                    let capability_labels: Vec<Value> = capabilities
                        .into_iter()
                        .map(|cap| Value::from(capability_name(cap).to_string()))
                        .collect();
                    gateway_refusal_response(
                        &state,
                        StatusCode::PRECONDITION_REQUIRED,
                        "unsupported_capability",
                        format!(
                            "provider advert declares unsupported capabilities for profile {}",
                            advert_profile
                        ),
                        Some(&advert_profile),
                        Some(&advert_provider_id),
                        TELEMETRY_ENDPOINT_PROVIDER_ADVERT,
                        [("capabilities", Value::Array(capability_labels))],
                    )
                }
                other => json_error(StatusCode::BAD_REQUEST, format_advert_error(other)),
            }
        }
    }
}

pub(crate) async fn handle_get_sorafs_capacity_state(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs capacity registry API is not enabled on this node");
    }
    let query = match CapacityStateReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);

    let world = state.state.world_view();
    let snapshot = collect_snapshot(&world);

    let snapshot = match snapshot {
        Ok(snapshot) => snapshot,
        Err(err) => {
            error!(?err, "failed to collect capacity registry snapshot");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to collect capacity registry snapshot",
            );
        }
    };

    let local_usage = state.sorafs_node.capacity_usage();
    let local_metering = state.sorafs_node.metering_snapshot();
    let telemetry_preview =
        build_telemetry_preview_json(state.sorafs_node.build_capacity_telemetry());
    let fee_projection = local_usage
        .provider_id
        .and_then(|id| FeeProjection::from_snapshot(id, &local_metering));

    match snapshot_to_json(
        snapshot,
        &local_usage,
        &local_metering,
        telemetry_preview,
        fee_projection.as_ref(),
        limit,
    ) {
        Ok(value) => JsonBody(value).into_response(),
        Err(err) => {
            error!(?err, "failed to serialize capacity registry snapshot");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize capacity registry snapshot",
            )
        }
    }
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_state(
    State(state): State<SharedAppState>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }

    let schedulers = state.sorafs_node.schedulers();
    let telemetry = schedulers.telemetry_snapshot();
    let utilisation = schedulers.utilisation_snapshot();

    let response = StorageStateResponseDto {
        bytes_used: telemetry.bytes_used,
        bytes_capacity: telemetry.bytes_capacity,
        pin_queue_depth: telemetry.pin_queue_depth as u64,
        fetch_inflight: telemetry.fetch_inflight as u64,
        fetch_bytes_per_sec: telemetry.fetch_bytes_per_sec,
        por_inflight: telemetry.por_inflight as u64,
        por_samples_success_total: telemetry.por_samples_success,
        por_samples_failed_total: telemetry.por_samples_failed,
        fetch_utilisation_bps: utilisation.fetch_utilisation_bps,
        pin_queue_utilisation_bps: utilisation.pin_queue_utilisation_bps,
        por_utilisation_bps: utilisation.por_utilisation_bps,
    };

    record_storage_metrics(&state);

    let value = match norito::json::to_value(&response) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to encode storage scheduler state");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode storage scheduler state",
            );
        }
    };

    JsonBody(value).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_por_ingestion(
    State(state): State<SharedAppState>,
    Path(manifest_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match PorIngestionReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let manifest_digest = match parse_hex_fixed::<32>(&manifest_hex, "manifest_digest_hex") {
        Ok(bytes) => bytes,
        Err(err) => {
            return json_error(StatusCode::BAD_REQUEST, &err);
        }
    };
    let status = match state.sorafs_node.por_ingestion_status(&manifest_digest) {
        Ok(status) => status,
        Err(NodeStorageError::Disabled) => return storage_disabled_response(),
        Err(NodeStorageError::Storage(err)) => {
            return node_storage_error_response(NodeStorageError::Storage(err));
        }
    };
    if status.providers.is_empty() {
        return json_error(
            StatusCode::NOT_FOUND,
            "no PoR ingestion data recorded for the requested manifest",
        );
    }
    record_storage_metrics(&state);
    let provider_count = status.providers.len();
    let providers = status
        .providers
        .into_iter()
        .take(limit)
        .map(|entry| PorIngestionProviderStatusDto {
            provider_id_hex: hex::encode(entry.provider_id),
            pending_challenges: entry.pending_challenges,
            oldest_epoch_id: entry.oldest_epoch_id,
            oldest_response_deadline_unix: entry.oldest_response_deadline_unix,
            last_success_unix: entry.last_success_unix,
            last_failure_unix: entry.last_failure_unix,
            failures_total: entry.failures_total,
            consecutive_failures: entry.consecutive_failures,
        })
        .collect::<Vec<_>>();
    let returned_provider_count = providers.len();
    let response = PorIngestionStatusResponseDto {
        manifest_digest_hex: hex::encode(status.manifest_digest),
        provider_count: provider_count as u64,
        returned_provider_count: returned_provider_count as u64,
        limit: limit as u64,
        truncated_providers: provider_count > limit,
        providers,
    };
    let value = match norito::json::to_value(&response) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to encode PoR ingestion status response");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode PoR ingestion status response",
            );
        }
    };
    JsonBody(value).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_manifest(
    State(state): State<SharedAppState>,
    Path(manifest_id_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match StorageMetadataReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };

    let storage_manifest_id = match resolve_manifest_storage_id(&state, &manifest_id_hex) {
        Ok(manifest_id) => manifest_id,
        Err(response) => return response,
    };

    let stored = match state.sorafs_node.manifest_metadata(&storage_manifest_id) {
        Ok(manifest) => manifest,
        Err(err) => return node_storage_error_response(err),
    };

    if let Err(response) = enforce_chunker_support_gateway(
        &state,
        stored.chunk_profile_handle(),
        TELEMETRY_ENDPOINT_MANIFEST,
    ) {
        return response;
    }

    let manifest_bytes = match fs::read(stored.manifest_path()) {
        Ok(bytes) => bytes,
        Err(err) => {
            error!(?err, "failed to read stored manifest bytes");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to read stored manifest bytes",
            );
        }
    };

    let manifest_b64 = base64::engine::general_purpose::STANDARD.encode(manifest_bytes.as_slice());
    let file_count = stored.files().len();
    let limit = query
        .limit
        .map(|limit| normalize_limit(Some(limit)))
        .unwrap_or(file_count);
    let files = stored
        .files()
        .iter()
        .take(limit)
        .map(storage_stored_file_dto)
        .collect::<Vec<_>>();
    let returned_file_count = files.len();

    let response = StorageManifestResponseDto {
        manifest_id_hex,
        manifest_b64,
        manifest_digest_hex: hex::encode(stored.manifest_digest()),
        payload_digest_hex: hex::encode(stored.payload_digest()),
        content_length: stored.content_length(),
        chunk_count: stored.chunk_count() as u64,
        chunk_profile_handle: stored.chunk_profile_handle().to_owned(),
        stored_at_unix_secs: stored.stored_at_unix_secs(),
        files,
    };

    let mut value = match norito::json::to_value(&response) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to encode manifest response");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode manifest response",
            );
        }
    };
    if let Value::Object(ref mut obj) = value {
        obj.insert("file_count".into(), Value::from(file_count as u64));
        obj.insert(
            "returned_file_count".into(),
            Value::from(returned_file_count as u64),
        );
        obj.insert("limit".into(), Value::from(limit as u64));
        obj.insert("truncated_files".into(), Value::from(file_count > limit));
    }

    JsonBody(value).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_plan(
    State(state): State<SharedAppState>,
    Path(manifest_id_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match StorageMetadataReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);

    let storage_manifest_id = match resolve_manifest_storage_id(&state, &manifest_id_hex) {
        Ok(manifest_id) => manifest_id,
        Err(response) => return response,
    };

    let stored = match state.sorafs_node.manifest_metadata(&storage_manifest_id) {
        Ok(manifest) => manifest,
        Err(err) => return node_storage_error_response(err),
    };

    if let Err(response) = enforce_chunker_support_gateway(
        &state,
        stored.chunk_profile_handle(),
        TELEMETRY_ENDPOINT_PLAN,
    ) {
        return response;
    }

    let manifest_v1 = match stored.load_manifest() {
        Ok(manifest) => manifest,
        Err(err) => return storage_backend_error(err),
    };

    let chunk_profile = match chunk_profile_for_manifest(&manifest_v1) {
        Ok(profile) => profile,
        Err(err) => return err.into_response(),
    };

    let taikai_hint = match sorafs_car::taikai_segment_hint_from_sorafs_manifest(&manifest_v1) {
        Ok(hint) => hint,
        Err(err) => {
            error!(
                ?err,
                manifest = manifest_id_hex,
                "failed to derive Taikai segment hint from manifest"
            );
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to derive Taikai metadata",
            );
        }
    };

    let plan = stored.to_car_plan_with_hint(chunk_profile, taikai_hint.clone());
    let specs = plan.chunk_fetch_specs();
    let file_count = stored.files().len();
    let files = stored
        .files()
        .iter()
        .take(limit)
        .map(file_listing_entry_json)
        .collect::<Vec<_>>();
    let returned_file_count = files.len();
    let chunk_count = specs.len();

    let chunk_digests = specs
        .iter()
        .take(limit)
        .map(|spec| Value::String(hex::encode(spec.digest)))
        .collect::<Vec<_>>();
    let chunks = specs
        .iter()
        .take(limit)
        .map(chunk_fetch_spec_json)
        .collect::<Vec<_>>();

    let mut plan_map = Map::new();
    plan_map.insert("chunk_count".into(), Value::from(chunk_count as u64));
    plan_map.insert(
        "returned_chunk_count".into(),
        Value::from(chunks.len() as u64),
    );
    plan_map.insert("limit".into(), Value::from(limit as u64));
    plan_map.insert("truncated_chunks".into(), Value::from(chunk_count > limit));
    plan_map.insert("content_length".into(), Value::from(plan.content_length));
    plan_map.insert(
        "payload_digest_blake3".into(),
        Value::String(hex::encode(plan.payload_digest.as_bytes())),
    );
    plan_map.insert(
        "chunk_profile_handle".into(),
        Value::String(stored.chunk_profile_handle().to_owned()),
    );
    plan_map.insert("file_count".into(), Value::from(file_count as u64));
    plan_map.insert(
        "returned_file_count".into(),
        Value::from(returned_file_count as u64),
    );
    plan_map.insert("truncated_files".into(), Value::from(file_count > limit));
    plan_map.insert("files".into(), Value::Array(files));
    plan_map.insert("chunk_digest_count".into(), Value::from(chunk_count as u64));
    plan_map.insert(
        "returned_chunk_digest_count".into(),
        Value::from(chunk_digests.len() as u64),
    );
    plan_map.insert(
        "truncated_chunk_digests".into(),
        Value::from(chunk_count > limit),
    );
    plan_map.insert("chunk_digests_blake3".into(), Value::Array(chunk_digests));
    plan_map.insert("chunks".into(), Value::Array(chunks));

    let mut root = Map::new();
    root.insert("manifest_id_hex".into(), Value::String(manifest_id_hex));
    root.insert("plan".into(), Value::Object(plan_map));

    JsonBody(Value::Object(root)).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_pin_registry(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }

    let query = match PinListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };

    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|hdr| &hdr.0)) {
        Ok(format) => format,
        Err(err) => return err.into_response(),
    };

    let (attestation, snapshot) = match pin_snapshot_with_attestation(&state) {
        Ok(snapshot) => snapshot,
        Err(err) => return err.into_response(),
    };

    let status_filter = match query.status.as_deref() {
        Some(value) => match parse_pin_status_filter(value) {
            Some(filter) => Some(filter),
            None => {
                return json_error(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "invalid status filter `{value}`; expected pending, approved, or retired"
                    ),
                );
            }
        },
        None => None,
    };

    let mut manifests: Vec<&RegistryManifest> = snapshot.manifests.iter().collect();
    if let Some(filter) = status_filter {
        manifests.retain(|manifest| filter.matches(manifest.status_label()));
    }
    let policy = &state.sorafs_alias_cache_policy;
    let enforcement = state.sorafs_alias_enforcement;
    let now_secs = crate::sorafs::unix_now_secs();

    let total = manifests.len();
    let limit = normalize_limit(query.limit);
    let offset = normalize_offset(query.offset, total);
    let end = offset.saturating_add(limit).min(total);

    let page = &manifests[offset..end];
    let mut manifests_json = Vec::with_capacity(page.len());
    for manifest in page {
        let mut value = match manifest.to_json() {
            Ok(value) => value,
            Err(err) => {
                error!(?err, "failed to serialize pin registry manifests");
                return json_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "failed to serialize pin registry manifests",
                );
            }
        };
        if let Value::Object(mut map) = value {
            let lineage = snapshot.lineage_for(manifest.digest_hex());
            map.insert("lineage".into(), lineage_to_json(&lineage));
            if let Some(alias) = snapshot
                .aliases
                .iter()
                .find(|alias| alias.manifest_digest_hex() == manifest.digest_hex())
            {
                let governance = manifest.governance_summary();
                match prepare_alias_presentation(
                    alias,
                    &lineage,
                    &governance,
                    policy,
                    enforcement,
                    &state.telemetry,
                    now_secs,
                ) {
                    Ok(presentation) => {
                        map.insert(
                            "cache_evaluation".into(),
                            build_cache_evaluation_json(
                                &presentation.evaluation,
                                &presentation.decision,
                                policy,
                            ),
                        );
                    }
                    Err(err) => return err.into_response(),
                }
            }
            value = Value::Object(map);
        }
        manifests_json.push(value);
    }

    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("total_count", total as u64),
        json_entry("returned_count", manifests_json.len() as u64),
        json_entry("offset", offset as u64),
        json_entry("limit", limit as u64),
        json_entry("manifests", Value::Array(manifests_json)),
    ]);
    match format {
        crate::utils::ResponseFormat::Json => {
            crate::utils::respond_value_with_format(response, format)
        }
        crate::utils::ResponseFormat::Norito => {
            let json_text = match json::to_string(&response) {
                Ok(value) => value,
                Err(err) => {
                    error!(?err, "failed to serialize pin registry response");
                    return json_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "failed to serialize pin registry response",
                    );
                }
            };
            let bytes = match norito::to_bytes(&json_text) {
                Ok(bytes) => bytes,
                Err(err) => {
                    error!(?err, "failed to encode pin registry Norito response");
                    return json_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "failed to encode pin registry response",
                    );
                }
            };
            Response::builder()
                .status(StatusCode::OK)
                .header(header::CONTENT_TYPE, crate::utils::NORITO_MIME_TYPE)
                .body(Body::from(bytes))
                .expect("build pin registry Norito response")
        }
    }
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_pin_manifest(
    State(state): State<SharedAppState>,
    Path(digest_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }

    let query = match PinManifestReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);

    let format = match crate::utils::negotiate_json_only_response(accept.as_ref().map(|hdr| &hdr.0))
    {
        Ok(()) => crate::utils::ResponseFormat::Json,
        Err(err) => return err.into_response(),
    };

    let canonical_digest = match parse_manifest_digest_hex(&digest_hex) {
        Ok(bytes) => hex::encode(bytes),
        Err(err) => return err.into_response(),
    };

    let (attestation, snapshot) = match pin_snapshot_with_attestation(&state) {
        Ok(snapshot) => snapshot,
        Err(err) => return err.into_response(),
    };

    let manifest = match snapshot
        .manifests
        .iter()
        .find(|manifest| manifest.digest_hex() == canonical_digest)
    {
        Some(manifest) => manifest,
        None => {
            return json_error(
                StatusCode::NOT_FOUND,
                format!("manifest `{}` not found in pin registry", digest_hex),
            );
        }
    };

    let chunker_handle = manifest.chunker_handle();
    if state.sorafs_gateway_config.enforce_capabilities {
        let (support, _, supported_profiles) = chunker_support_state(&state, &chunker_handle);
        match support {
            ChunkerSupport::Supported => {}
            ChunkerSupport::Unsupported => {
                return registry_chunker_error(&chunker_handle, &supported_profiles);
            }
            ChunkerSupport::Unknown => {
                return registry_chunker_unknown(&chunker_handle);
            }
        }
    }

    let manifest_lineage = snapshot.lineage_for(&canonical_digest);
    let manifest_json = match manifest.to_json() {
        Ok(mut value) => {
            if let Value::Object(mut map) = value {
                map.insert("lineage".into(), lineage_to_json(&manifest_lineage));
                value = Value::Object(map);
            }
            value
        }
        Err(err) => {
            error!(?err, "failed to serialize pin registry manifest");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize pin registry manifest",
            );
        }
    };

    let policy = &state.sorafs_alias_cache_policy;
    let enforcement = state.sorafs_alias_enforcement;
    let now_secs = crate::sorafs::unix_now_secs();

    let aliases = snapshot
        .aliases
        .iter()
        .filter(|alias| alias.manifest_digest_hex() == canonical_digest)
        .collect::<Vec<_>>();
    let alias_count = aliases.len();
    let alias_page_end = limit.min(alias_count);
    let aliases = &aliases[..alias_page_end];
    let mut alias_presentations = Vec::with_capacity(aliases.len());
    let mut alias_values = Vec::with_capacity(aliases.len());
    for &alias in aliases {
        let manifest_for_alias = match snapshot.manifest_by_digest(alias.manifest_digest_hex()) {
            Some(record) => record,
            None => {
                error!(
                    alias = alias.alias_label(),
                    manifest = alias.manifest_digest_hex(),
                    "alias references manifest missing from registry snapshot"
                );
                return json_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    format!(
                        "alias `{}` references unknown manifest `{}`",
                        alias.alias_label(),
                        alias.manifest_digest_hex()
                    ),
                )
                .into_response();
            }
        };
        let lineage_summary = if manifest_for_alias.digest_hex() == canonical_digest {
            manifest_lineage.clone()
        } else {
            snapshot.lineage_for(alias.manifest_digest_hex())
        };
        let governance_summary = manifest_for_alias.governance_summary();

        match prepare_alias_presentation(
            alias,
            &lineage_summary,
            &governance_summary,
            policy,
            enforcement,
            &state.telemetry,
            now_secs,
        ) {
            Ok(presentation) => {
                alias_values.push(presentation.json.clone());
                alias_presentations.push(presentation);
            }
            Err(err) => return err.into_response(),
        }
    }

    if let Some(primary) = alias_presentations.first() {
        if matches!(
            primary.decision.outcome,
            crate::sorafs::CacheDecisionOutcome::Refuse
        ) {
            warn!(
                alias = %primary.alias_label,
                reasons = ?primary.decision.reasons,
                "alias proof rejected; refusing manifest response"
            );
            let status = status_code_for_decision(&primary.decision);
            let message = message_for_decision(&primary.decision);
            return alias_policy_error_response(primary, policy, status, message);
        }
    }

    let orders = snapshot
        .replication_orders
        .iter()
        .filter(|order| order.manifest_digest_hex() == canonical_digest)
        .collect::<Vec<_>>();
    let replication_order_count = orders.len();
    let order_page_end = limit.min(replication_order_count);
    let orders = &orders[..order_page_end];
    let order_values = match orders
        .iter()
        .map(|&order| order.to_json())
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(values) => values,
        Err(err) => {
            error!(?err, "failed to serialize replication orders");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize replication orders",
            );
        }
    };

    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("manifest", manifest_json),
        json_entry("alias_count", alias_count as u64),
        json_entry("returned_alias_count", alias_values.len() as u64),
        json_entry("truncated_aliases", alias_count > limit),
        json_entry("replication_order_count", replication_order_count as u64),
        json_entry(
            "returned_replication_order_count",
            order_values.len() as u64,
        ),
        json_entry(
            "truncated_replication_orders",
            replication_order_count > limit,
        ),
        json_entry("limit", limit as u64),
        json_entry("aliases", Value::Array(alias_values)),
        json_entry("replication_orders", Value::Array(order_values)),
    ]);

    let mut http_response = crate::utils::respond_value_with_format(response, format);
    if let Some(primary) = alias_presentations.first() {
        let headers = http_response.headers_mut();
        if let Ok(name) = HeaderValue::from_str(&primary.alias_label) {
            headers.insert(HeaderName::from_static(HEADER_SORA_NAME), name);
        }
        if let Ok(cid) = HeaderValue::from_str(&primary.manifest_digest_hex) {
            headers.insert(HeaderName::from_static(HEADER_SORA_CID), cid);
        }
        if let Ok(proof) = HeaderValue::from_str(&primary.proof_b64) {
            headers.insert(HeaderName::from_static(HEADER_SORA_PROOF), proof);
        }
        headers.insert(CACHE_CONTROL, policy.cache_control_header());
        if let Ok(status) = HeaderValue::from_str(&primary.status_label) {
            headers.insert(HeaderName::from_static(HEADER_SORA_PROOF_STATUS), status);
        }
        headers.insert(AGE, primary.evaluation.age_header());
        if let Some(warning) = decision_warning_header(&primary.decision) {
            headers.append(WARNING, warning);
        } else if let Some(warning) = primary.evaluation.warning_header() {
            headers.append(WARNING, warning);
        }
    }

    http_response
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_aliases(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }

    let query = match AliasListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };

    let format = match crate::utils::negotiate_json_only_response(accept.as_ref().map(|hdr| &hdr.0))
    {
        Ok(()) => crate::utils::ResponseFormat::Json,
        Err(err) => return err.into_response(),
    };

    let (attestation, snapshot) = match pin_snapshot_with_attestation(&state) {
        Ok(snapshot) => snapshot,
        Err(err) => return err.into_response(),
    };

    let namespace_filter = query.namespace.as_deref().map(str::to_ascii_lowercase);
    let digest_filter = query
        .manifest_digest
        .as_deref()
        .map(str::to_ascii_lowercase);

    let mut aliases: Vec<&RegistryAlias> = snapshot.aliases.iter().collect();
    if let Some(namespace) = namespace_filter {
        aliases.retain(|alias| alias.namespace().eq_ignore_ascii_case(&namespace));
    }
    if let Some(digest) = digest_filter {
        aliases.retain(|alias| alias.manifest_digest_hex().eq_ignore_ascii_case(&digest));
    }

    let total = aliases.len();
    let limit = normalize_limit(query.limit);
    let offset = normalize_offset(query.offset, total);
    let end = offset.saturating_add(limit).min(total);

    let page = &aliases[offset..end];
    let mut alias_values = Vec::with_capacity(page.len());
    let policy = &state.sorafs_alias_cache_policy;
    let enforcement = state.sorafs_alias_enforcement;
    let now_secs = crate::sorafs::unix_now_secs();
    for alias in page {
        let lineage_summary = snapshot.lineage_for(alias.manifest_digest_hex());
        let manifest_for_alias = match snapshot.manifest_by_digest(alias.manifest_digest_hex()) {
            Some(manifest) => manifest,
            None => {
                error!(
                    alias = alias.alias_label(),
                    manifest = alias.manifest_digest_hex(),
                    "alias references manifest missing from registry snapshot"
                );
                return json_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    format!(
                        "alias `{}` references unknown manifest `{}`",
                        alias.alias_label(),
                        alias.manifest_digest_hex()
                    ),
                )
                .into_response();
            }
        };
        let governance_summary = manifest_for_alias.governance_summary();
        match prepare_alias_presentation(
            alias,
            &lineage_summary,
            &governance_summary,
            policy,
            enforcement,
            &state.telemetry,
            now_secs,
        ) {
            Ok(presentation) => alias_values.push(presentation.json),
            Err(err) => return err.into_response(),
        }
    }

    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("total_count", total as u64),
        json_entry("returned_count", alias_values.len() as u64),
        json_entry("offset", offset as u64),
        json_entry("limit", limit as u64),
        json_entry("aliases", Value::Array(alias_values)),
    ]);
    crate::utils::respond_value_with_format(response, format)
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_replication_orders(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }

    let query = match ReplicationListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };

    let format = match crate::utils::negotiate_json_only_response(accept.as_ref().map(|hdr| &hdr.0))
    {
        Ok(()) => crate::utils::ResponseFormat::Json,
        Err(err) => return err.into_response(),
    };

    let (attestation, snapshot) = match pin_snapshot_with_attestation(&state) {
        Ok(snapshot) => snapshot,
        Err(err) => return err.into_response(),
    };

    let status_filter = match query.status.as_deref() {
        Some(value) => match parse_replication_status_filter(value) {
            Some(filter) => Some(filter),
            None => {
                return json_error(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "invalid status filter `{value}`; expected pending, completed, or expired"
                    ),
                );
            }
        },
        None => None,
    };

    let digest_filter = query
        .manifest_digest
        .as_deref()
        .map(str::to_ascii_lowercase);

    let mut orders: Vec<&RegistryReplicationOrder> = snapshot.replication_orders.iter().collect();
    if let Some(filter) = status_filter {
        orders.retain(|order| filter.matches(order.status_label()));
    }
    if let Some(digest) = digest_filter {
        orders.retain(|order| order.manifest_digest_hex().eq_ignore_ascii_case(&digest));
    }

    let total = orders.len();
    let limit = normalize_limit(query.limit);
    let offset = normalize_offset(query.offset, total);
    let end = offset.saturating_add(limit).min(total);

    let page = &orders[offset..end];
    let order_values = match page
        .iter()
        .map(|order| order.to_json())
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(values) => values,
        Err(err) => {
            error!(?err, "failed to serialize replication orders");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize replication orders",
            );
        }
    };

    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("total_count", total as u64),
        json_entry("returned_count", order_values.len() as u64),
        json_entry("offset", offset as u64),
        json_entry("limit", limit as u64),
        json_entry("replication_orders", Value::Array(order_values)),
    ]);
    crate::utils::respond_value_with_format(response, format)
}

fn build_plan_for_storage_pin_request(
    payload: &[u8],
    profile: ChunkProfile,
    files: Option<&[StorageFileEntryDto]>,
) -> Result<CarBuildPlan, String> {
    let Some(files) = files else {
        return CarBuildPlan::single_file_with_profile(payload, profile)
            .map_err(|err| format!("failed to derive chunk plan: {err}"));
    };

    if files.is_empty() {
        return Err("files must not be empty when provided".to_string());
    }

    let mut cursor = 0usize;
    let mut entries = Vec::with_capacity(files.len());
    for file in files {
        let size = usize::try_from(file.size)
            .map_err(|_| format!("file `{}` exceeds host limits", file.path.join("/")))?;
        let end = cursor
            .checked_add(size)
            .ok_or_else(|| format!("file `{}` overflows payload bounds", file.path.join("/")))?;
        if end > payload.len() {
            return Err(format!(
                "file `{}` exceeds payload length",
                file.path.join("/")
            ));
        }
        entries.push(FileEntry {
            path: file.path.clone(),
            data: payload[cursor..end].to_vec(),
        });
        cursor = end;
    }

    if cursor != payload.len() {
        return Err(format!(
            "file sizes total {} but payload length is {}",
            cursor,
            payload.len()
        ));
    }

    let (plan, rebuilt_payload) = CarBuildPlan::from_files_with_profile(entries, profile)
        .map_err(|err| format!("failed to derive chunk plan: {err}"))?;
    debug_assert_eq!(rebuilt_payload, payload);
    Ok(plan)
}

fn dm_storage_class_from_manifest(
    class: sorafs_manifest::StorageClass,
) -> iroha_data_model::sorafs::pin_registry::StorageClass {
    match class {
        sorafs_manifest::StorageClass::Hot => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Hot
        }
        sorafs_manifest::StorageClass::Warm => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Warm
        }
        sorafs_manifest::StorageClass::Cold => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Cold
        }
    }
}

fn paid_pin_record_for_manifest(
    state: &SharedAppState,
    digest: ManifestDigest,
    manifest: &ManifestV1,
    plan: &CarBuildPlan,
) -> ApiResult<PinManifestRecord> {
    let state_view = state.state.view();
    let Some(record) = state_view.world().pin_manifests().get(&digest).cloned() else {
        return Err(json_error(
            StatusCode::PAYMENT_REQUIRED,
            format!(
                "manifest {} has no paid pin registry record",
                hex::encode(digest.as_bytes())
            ),
        )
        .into());
    };

    if record.digest != digest {
        return Err(json_error(
            StatusCode::CONFLICT,
            "paid pin registry record digest does not match the requested manifest",
        )
        .into());
    }

    match record.status {
        PinStatus::Approved(_) => {}
        PinStatus::Retired(_) => {
            return Err(json_error(
                StatusCode::FORBIDDEN,
                format!("manifest {} is retired", hex::encode(digest.as_bytes())),
            )
            .into());
        }
        PinStatus::Pending => {
            return Err(json_error(
                StatusCode::PAYMENT_REQUIRED,
                format!(
                    "manifest {} is not approved for pinning",
                    hex::encode(digest.as_bytes())
                ),
            )
            .into());
        }
    }

    let profile_matches = record.chunker.profile_id == manifest.chunking.profile_id.0
        && record.chunker.namespace == manifest.chunking.namespace
        && record.chunker.name == manifest.chunking.name
        && record.chunker.semver == manifest.chunking.semver
        && record.chunker.multihash_code == manifest.chunking.multihash_code;
    if !profile_matches {
        return Err(json_error(
            StatusCode::CONFLICT,
            "manifest chunker profile does not match the paid pin record",
        )
        .into());
    }

    let policy_matches = record.policy.min_replicas == manifest.pin_policy.min_replicas
        && record.policy.retention_epoch == manifest.pin_policy.retention_epoch
        && record.policy.storage_class
            == dm_storage_class_from_manifest(manifest.pin_policy.storage_class);
    if !policy_matches {
        return Err(json_error(
            StatusCode::CONFLICT,
            "manifest pin policy does not match the paid pin record",
        )
        .into());
    }

    if record.content_length != manifest.content_length
        || record.content_length != plan.content_length
    {
        return Err(json_error(
            StatusCode::CONFLICT,
            "manifest content length does not match the paid pin record",
        )
        .into());
    }

    let chunk_digest = compute_chunk_plan_digest_sha3(&plan.chunks);
    if record.chunk_digest_sha3_256 != chunk_digest {
        return Err(json_error(
            StatusCode::CONFLICT,
            "chunk plan digest does not match the paid pin record",
        )
        .into());
    }

    let Some(payment) = record.pin_fee_payment.as_ref() else {
        return Err(json_error(
            StatusCode::PAYMENT_REQUIRED,
            "paid pin registry record is missing fee payment metadata",
        )
        .into());
    };
    if payment.paid_by != record.submitted_by {
        return Err(json_error(
            StatusCode::PAYMENT_REQUIRED,
            "paid pin registry record payer does not match the manifest submitter",
        )
        .into());
    }

    Ok(record)
}

#[derive(Debug, Clone)]
struct ResolvedSiteHost {
    hostname: String,
    index_document: String,
    spa_fallback: bool,
    stored: StoredManifest,
}

fn normalized_site_request_host(headers: &HeaderMap) -> Result<String, Response> {
    let Some(host) = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
    else {
        return Err(json_error(StatusCode::BAD_REQUEST, "missing Host header"));
    };

    normalize_host_header(host)
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "invalid Host header"))
}

fn extract_cid_from_untrusted_host(
    host: &str,
    config: &iroha_config::parameters::actual::SorafsGatewayUntrustedHosting,
) -> Result<Option<String>, Response> {
    if !config.enabled {
        return Ok(None);
    }

    for suffix in [
        config.cid_host_suffixes.live.as_str(),
        config.cid_host_suffixes.taira.as_str(),
    ] {
        if suffix.is_empty() {
            continue;
        }

        let marker = format!(".{suffix}");
        let Some(cid_label) = host.strip_suffix(&marker) else {
            continue;
        };
        if cid_label.is_empty() || cid_label.contains('.') {
            continue;
        }

        if decode_content_cid(cid_label).is_none() {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                "invalid content CID host",
            ));
        }

        return Ok(Some(cid_label.to_owned()));
    }

    Ok(None)
}

#[derive(Clone, Debug, JsonDeserialize)]
struct AuthoritativeAppStaticSiteBindingV1 {
    schema_version: u16,
    hostname: String,
    mount_path: String,
    index_document: String,
    spa_fallback: bool,
    manifest_digest_hex: String,
}

fn resolve_site_host_from_authoritative_app(
    state: &SharedAppState,
    host: &str,
) -> Result<Option<ResolvedSiteHost>, Response> {
    let state_view = state.state.view();
    let world = state_view.world();
    let mut best_candidate = None;

    for (service_id, deployment) in world.soracloud_service_deployments().iter() {
        let service_name = service_id.to_string();
        let Some(bundle) = world.soracloud_service_revisions().get(&(
            service_name.clone(),
            deployment.current_service_version.clone(),
        )) else {
            continue;
        };
        let Some(route) = bundle.service.route.as_ref() else {
            continue;
        };
        if route.visibility != SoraRouteVisibilityV1::Public {
            continue;
        }
        if !route.host.eq_ignore_ascii_case(host) {
            continue;
        }
        let Some(config_entry) = deployment.service_configs.get(APP_STATIC_SITE_CONFIG_NAME) else {
            continue;
        };
        let replace = best_candidate.as_ref().is_none_or(
            |(best_sequence, best_service_name, _best_config): &(
                u64,
                String,
                iroha_data_model::soracloud::SoraServiceConfigEntryV1,
            )| {
                config_entry.last_update_sequence > *best_sequence
                    || (config_entry.last_update_sequence == *best_sequence
                        && service_name < *best_service_name)
            },
        );
        if replace {
            best_candidate = Some((
                config_entry.last_update_sequence,
                service_name,
                config_entry.clone(),
            ));
        }
    }

    let Some((_sequence, service_name, config_entry)) = best_candidate else {
        return Ok(None);
    };
    let binding = config_entry
        .value_json
        .try_into_any_norito::<AuthoritativeAppStaticSiteBindingV1>()
        .map_err(|err| {
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!(
                    "authoritative static site binding for service `{service_name}` could not be decoded: {err}"
                ),
            )
        })?;
    if binding.schema_version != APP_STATIC_SITE_BINDING_SCHEMA_VERSION_V1 {
        return Err(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!(
                "authoritative static site binding for service `{service_name}` has unsupported schema_version `{}`",
                binding.schema_version
            ),
        ));
    }
    if !binding.hostname.eq_ignore_ascii_case(host) {
        return Err(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!(
                "authoritative static site binding for service `{service_name}` points at host `{}` but request host was `{host}`",
                binding.hostname
            ),
        ));
    }
    if binding.mount_path != "/" {
        return Err(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!(
                "authoritative static site binding for service `{service_name}` uses unsupported mount_path `{}`",
                binding.mount_path
            ),
        ));
    }

    let manifest_digest = parse_hex_fixed::<32>(
        &binding.manifest_digest_hex,
        "manifest_digest_hex",
    )
    .map_err(|err| {
        json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!(
                "authoritative static site binding for service `{service_name}` is invalid: {err}"
            ),
        )
    })?;
    let stored = state
        .sorafs_node
        .manifest_metadata_by_digest(&manifest_digest)
        .map_err(node_storage_error_response)?;
    enforce_site_denylist(state, &stored)?;

    Ok(Some(ResolvedSiteHost {
        hostname: binding.hostname,
        index_document: binding.index_document,
        spa_fallback: binding.spa_fallback,
        stored,
    }))
}

async fn resolve_site_host(
    state: &SharedAppState,
    headers: &HeaderMap,
) -> Result<ResolvedSiteHost, Response> {
    if !state.sorafs_node.is_enabled() {
        return Err(storage_disabled_response());
    }

    let host = normalized_site_request_host(headers)?;

    if let Some(cid) =
        extract_cid_from_untrusted_host(&host, &state.sorafs_gateway_config.untrusted_hosting)?
    {
        let stored = resolve_site_manifest_by_cid(state, &cid).await?;
        return Ok(ResolvedSiteHost {
            hostname: host,
            index_document: "index.html".to_owned(),
            spa_fallback: true,
            stored,
        });
    }

    if let Some(resolved) = resolve_site_host_from_authoritative_app(state, &host)? {
        return Ok(resolved);
    }

    let bindings = match load_site_bindings_from_env() {
        Ok(Some(document)) => document,
        Ok(None) => return Err(StatusCode::NOT_FOUND.into_response()),
        Err(err) => return Err(json_error(StatusCode::INTERNAL_SERVER_ERROR, err)),
    };

    let Some(binding) = find_site_binding(&bindings, &host).cloned() else {
        return Err(StatusCode::NOT_FOUND.into_response());
    };

    let manifest_digest =
        match parse_hex_fixed::<32>(&binding.manifest_digest_hex, "manifest_digest_hex") {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
        };

    let stored = match state
        .sorafs_node
        .manifest_metadata_by_digest(&manifest_digest)
    {
        Ok(manifest) => manifest,
        Err(err) => return Err(node_storage_error_response(err)),
    };

    enforce_site_denylist(state, &stored)?;

    let hostname = binding.hostname.clone();
    let index_document = binding.index_document().to_owned();
    let spa_fallback = binding.spa_fallback_enabled();
    Ok(ResolvedSiteHost {
        hostname,
        index_document,
        spa_fallback,
        stored,
    })
}

#[derive(Debug, Clone)]
struct RemoteCidSource {
    manifest_digest_hex: String,
    provider_id_hex: String,
    torii_base_url: reqwest::Url,
}

struct RemoteSiteBundle {
    manifest: ManifestV1,
    payload: Vec<u8>,
    files: Option<Vec<StorageFileEntryDto>>,
}

fn find_local_site_manifest_by_cid(
    state: &SharedAppState,
    cid_bytes: &[u8],
) -> Result<Option<StoredManifest>, Response> {
    if !state.sorafs_node.is_enabled() {
        return Err(storage_disabled_response());
    }

    let manifests = state
        .sorafs_node
        .stored_manifests()
        .map_err(node_storage_error_response)?;
    Ok(manifests
        .into_iter()
        .filter(|manifest| manifest.manifest_cid() == cid_bytes)
        .max_by_key(|manifest| {
            let files = manifest.files();
            let has_index_document = files
                .iter()
                .any(|file| file.path.len() == 1 && file.path[0] == "index.html");
            (has_index_document, files.len())
        }))
}

fn normalize_provider_torii_base_url(host_pattern: &str) -> Result<reqwest::Url, String> {
    let trimmed = host_pattern.trim();
    if trimmed.is_empty() {
        return Err("provider advert endpoint host pattern must not be empty".to_string());
    }

    let with_scheme = if trimmed.contains("://") {
        trimmed.to_owned()
    } else {
        let lower = trimmed.to_ascii_lowercase();
        let scheme = if lower.starts_with("localhost")
            || lower.starts_with("127.")
            || lower.starts_with("[::1]")
            || lower.starts_with("::1")
        {
            "http"
        } else {
            "https"
        };
        format!("{scheme}://{trimmed}")
    };

    let mut url = reqwest::Url::parse(&with_scheme)
        .map_err(|err| format!("invalid provider advert endpoint `{trimmed}`: {err}"))?;
    if !url.path().ends_with('/') {
        let normalized = format!("{}/", url.path());
        url.set_path(&normalized);
    }
    Ok(url)
}

fn storage_file_entries_from_manifest_response(
    files: &[StorageStoredFileDto],
) -> Result<Option<Vec<StorageFileEntryDto>>, String> {
    if files.is_empty() {
        return Ok(None);
    }

    let mut cursor = 0_u64;
    let mut entries = Vec::with_capacity(files.len());
    for file in files {
        if file.offset != cursor {
            return Err(format!(
                "remote manifest layout is non-contiguous at `{}`: expected offset {cursor}, found {}",
                file.path.join("/"),
                file.offset,
            ));
        }
        entries.push(StorageFileEntryDto {
            path: file.path.clone(),
            size: file.size,
        });
        cursor = cursor.saturating_add(file.size);
    }

    Ok(Some(entries))
}

async fn resolve_remote_cid_sources(
    state: &SharedAppState,
    cid_bytes: &[u8],
) -> Result<Option<Vec<RemoteCidSource>>, Response> {
    let snapshot = match pin_snapshot_with_attestation(state) {
        Ok((_, snapshot)) => snapshot,
        Err(err) => return Err(err.into_response()),
    };

    let mut provider_specs = Vec::<(String, String)>::new();
    for prefer_completed in [true, false] {
        for order in &snapshot.replication_orders {
            if order.manifest_cid() != cid_bytes {
                continue;
            }
            if order.is_expired() {
                continue;
            }
            if prefer_completed != order.completion_epoch().is_some() {
                continue;
            }
            let Some(manifest) = snapshot.manifest_by_digest(order.manifest_digest_hex()) else {
                continue;
            };
            if manifest.status_label() != "approved" {
                continue;
            }
            for provider_id_hex in order.providers() {
                if provider_specs.iter().any(|existing| {
                    existing.0 == order.manifest_digest_hex() && existing.1 == *provider_id_hex
                }) {
                    continue;
                }
                provider_specs.push((
                    order.manifest_digest_hex().to_owned(),
                    provider_id_hex.clone(),
                ));
            }
        }
    }

    if provider_specs.is_empty() {
        return Ok(None);
    }

    let Some(cache) = state.sorafs_cache.clone() else {
        return Err(json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "SoraFS discovery cache is not available for CID gateway fetch",
        ));
    };
    let cache = cache.read().await;

    let mut sources = Vec::new();
    for (manifest_digest_hex, provider_id_hex) in provider_specs {
        let provider_id = match decode_hex_32(&provider_id_hex) {
            Ok(bytes) => bytes,
            Err(_) => continue,
        };
        let Some(record) = cache.record_by_provider(&provider_id) else {
            continue;
        };
        let Some(endpoint) = record
            .advert()
            .body
            .endpoints
            .iter()
            .find(|endpoint| endpoint.kind == EndpointKind::Torii)
        else {
            continue;
        };
        let torii_base_url = match normalize_provider_torii_base_url(&endpoint.host_pattern) {
            Ok(url) => url,
            Err(err) => {
                warn!(
                    provider_id_hex = %provider_id_hex,
                    manifest_digest_hex = %manifest_digest_hex,
                    %err,
                    "ignoring invalid Torii endpoint advertised for CID gateway fetch"
                );
                continue;
            }
        };
        sources.push(RemoteCidSource {
            manifest_digest_hex,
            provider_id_hex,
            torii_base_url,
        });
    }

    if sources.is_empty() {
        return Err(json_error(
            StatusCode::BAD_GATEWAY,
            "no SoraFS Torii provider routes are available for the requested CID",
        ));
    }

    Ok(Some(sources))
}

async fn fetch_remote_site_bundle_from_source(
    client: &reqwest::Client,
    source: &RemoteCidSource,
    cid_bytes: &[u8],
) -> Result<RemoteSiteBundle, String> {
    let manifest_url = source
        .torii_base_url
        .join(&format!(
            "v1/sorafs/storage/manifest/{}",
            source.manifest_digest_hex
        ))
        .map_err(|err| format!("failed to build remote manifest URL: {err}"))?;
    let manifest_response = client
        .get(manifest_url)
        .send()
        .await
        .map_err(|err| format!("failed to fetch remote manifest metadata: {err}"))?;
    let manifest_status = manifest_response.status();
    let manifest_body = manifest_response
        .bytes()
        .await
        .map_err(|err| format!("failed to read remote manifest metadata: {err}"))?;
    if !manifest_status.is_success() {
        let details = String::from_utf8_lossy(&manifest_body);
        return Err(format!(
            "remote manifest endpoint returned {manifest_status}: {}",
            details.trim()
        ));
    }
    let manifest_response = norito::json::from_slice::<StorageManifestResponseDto>(&manifest_body)
        .map_err(|err| format!("failed to decode remote manifest metadata response: {err}"))?;
    if manifest_response.manifest_digest_hex != source.manifest_digest_hex {
        return Err(format!(
            "remote manifest digest mismatch: expected {}, found {}",
            source.manifest_digest_hex, manifest_response.manifest_digest_hex
        ));
    }

    let manifest_bytes = BASE64_STANDARD
        .decode(manifest_response.manifest_b64.as_bytes())
        .map_err(|err| format!("failed to decode remote manifest payload: {err}"))?;
    let manifest: ManifestV1 = norito::decode_from_bytes(&manifest_bytes)
        .map_err(|err| format!("failed to decode remote manifest bytes: {err}"))?;
    if manifest.root_cid != cid_bytes {
        return Err("remote manifest CID does not match requested CID".to_string());
    }
    let manifest_digest = manifest.digest().map_err(|err| err.to_string())?;
    let manifest_digest_hex = hex::encode(manifest_digest.as_bytes());
    if manifest_digest_hex != source.manifest_digest_hex {
        return Err(format!(
            "decoded remote manifest digest mismatch: expected {}, found {manifest_digest_hex}",
            source.manifest_digest_hex
        ));
    }
    if manifest_response.content_length > usize::MAX as u64 {
        return Err("remote payload exceeds host limits".to_string());
    }

    let fetch_body = norito::json::to_vec(&StorageFetchRequestDto {
        manifest_id_hex: manifest_response.manifest_id_hex.clone(),
        offset: 0,
        length: manifest_response.content_length,
        provider_id_hex: Some(source.provider_id_hex.clone()),
    })
    .map_err(|err| format!("failed to encode remote fetch request: {err}"))?;
    let fetch_url = source
        .torii_base_url
        .join("v1/sorafs/storage/fetch")
        .map_err(|err| format!("failed to build remote payload URL: {err}"))?;
    let fetch_response = client
        .post(fetch_url)
        .header(header::CONTENT_TYPE.as_str(), "application/json")
        .header(HEADER_SORA_MANIFEST_ENVELOPE, "cid-gateway-fetch")
        .body(fetch_body)
        .send()
        .await
        .map_err(|err| format!("failed to fetch remote site payload: {err}"))?;
    let fetch_status = fetch_response.status();
    let fetch_body = fetch_response
        .bytes()
        .await
        .map_err(|err| format!("failed to read remote site payload response: {err}"))?;
    if !fetch_status.is_success() {
        let details = String::from_utf8_lossy(&fetch_body);
        return Err(format!(
            "remote payload endpoint returned {fetch_status}: {}",
            details.trim()
        ));
    }
    let fetch_response = norito::json::from_slice::<StorageFetchResponseDto>(&fetch_body)
        .map_err(|err| format!("failed to decode remote site payload response: {err}"))?;
    let payload = BASE64_STANDARD
        .decode(fetch_response.data_b64.as_bytes())
        .map_err(|err| format!("failed to decode remote site payload bytes: {err}"))?;
    if payload.len() as u64 != manifest_response.content_length {
        return Err(format!(
            "remote payload length mismatch: expected {}, found {}",
            manifest_response.content_length,
            payload.len()
        ));
    }

    let files = storage_file_entries_from_manifest_response(&manifest_response.files)?;
    Ok(RemoteSiteBundle {
        manifest,
        payload,
        files,
    })
}

async fn fetch_remote_site_bundle(
    state: &SharedAppState,
    cid_bytes: &[u8],
) -> Result<Option<RemoteSiteBundle>, Response> {
    let Some(sources) = resolve_remote_cid_sources(state, cid_bytes).await? else {
        return Ok(None);
    };
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(20))
        .build()
        .map_err(|err| {
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("failed to build CID gateway fetch client: {err}"),
            )
        })?;

    let mut last_error = None;
    for source in &sources {
        match fetch_remote_site_bundle_from_source(&client, source, cid_bytes).await {
            Ok(bundle) => return Ok(Some(bundle)),
            Err(err) => {
                warn!(
                    provider_id_hex = %source.provider_id_hex,
                    manifest_digest_hex = %source.manifest_digest_hex,
                    %err,
                    "failed to hydrate CID gateway cache from remote provider"
                );
                last_error = Some(err);
            }
        }
    }

    Err(json_error(
        StatusCode::BAD_GATEWAY,
        format!(
            "failed to fetch the requested CID from remote SoraFS providers{}",
            last_error
                .as_deref()
                .map(|err| format!(": {err}"))
                .unwrap_or_default()
        ),
    ))
}

fn cache_remote_site_bundle(
    state: &SharedAppState,
    bundle: RemoteSiteBundle,
) -> Result<StoredManifest, Response> {
    let profile =
        chunk_profile_for_manifest(&bundle.manifest).map_err(ResponseError::into_response)?;
    let plan =
        build_plan_for_storage_pin_request(&bundle.payload, profile, bundle.files.as_deref())
            .map_err(|err| json_error(StatusCode::BAD_GATEWAY, err))?;
    let manifest_digest: [u8; 32] = bundle
        .manifest
        .digest()
        .map_err(|err| {
            json_error(
                StatusCode::BAD_GATEWAY,
                format!("failed to digest remote manifest: {err}"),
            )
        })?
        .into();

    let mut reader = bundle.payload.as_slice();
    match state
        .sorafs_node
        .ingest_manifest(&bundle.manifest, &plan, &mut reader)
    {
        Ok(_) => {}
        Err(NodeStorageError::Storage(StorageBackendError::ManifestExists { .. })) => {}
        Err(err) => return Err(node_storage_error_response(err)),
    }

    state
        .sorafs_node
        .manifest_metadata_by_digest(&manifest_digest)
        .map_err(node_storage_error_response)
}

pub(crate) async fn resolve_site_manifest_by_cid_unchecked(
    state: &SharedAppState,
    cid: &str,
) -> Result<StoredManifest, Response> {
    let cid_bytes = decode_content_cid(cid)
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "invalid content CID"))?;
    let stored = if let Some(stored) = find_local_site_manifest_by_cid(state, &cid_bytes)? {
        stored
    } else if let Some(bundle) = fetch_remote_site_bundle(state, &cid_bytes).await? {
        cache_remote_site_bundle(state, bundle)?
    } else {
        return Err(StatusCode::NOT_FOUND.into_response());
    };

    Ok(stored)
}

async fn resolve_site_manifest_by_cid(
    state: &SharedAppState,
    cid: &str,
) -> Result<StoredManifest, Response> {
    let stored = resolve_site_manifest_by_cid_unchecked(state, cid).await?;
    enforce_site_denylist(state, &stored)?;
    Ok(stored)
}

fn enforce_site_denylist(state: &SharedAppState, stored: &StoredManifest) -> Result<(), Response> {
    let Some(denylist) = &state.sorafs_gateway_denylist else {
        return Ok(());
    };
    let now = SystemTime::now();
    let hit = denylist
        .check_manifest_digest(stored.manifest_digest(), now)
        .or_else(|| denylist.check_cid(stored.manifest_cid(), now));

    if let Some(hit) = hit {
        return Err(gateway_policy_violation_response(
            PolicyViolation::Denylisted(Box::new(hit)),
            None,
        ));
    }

    Ok(())
}

fn file_listing_entry_json(file: &StoredFileRecord) -> Value {
    let mut obj = Map::new();
    obj.insert(
        "path".into(),
        Value::Array(file.path.iter().cloned().map(Value::String).collect()),
    );
    obj.insert("offset".into(), Value::from(file.offset));
    obj.insert("size".into(), Value::from(file.size));
    obj.insert("first_chunk".into(), Value::from(file.first_chunk as u64));
    obj.insert("chunk_count".into(), Value::from(file.chunk_count as u64));
    Value::Object(obj)
}

fn bounded_file_listing_json(stored: &StoredManifest, limit: usize) -> (Vec<Value>, usize, bool) {
    let file_count = stored.files().len();
    let files = stored
        .files()
        .iter()
        .take(limit)
        .map(file_listing_entry_json)
        .collect();
    (files, file_count, file_count > limit)
}

fn optional_str_json(value: Option<&str>) -> Value {
    value.map_or(Value::Null, Value::from)
}

fn optional_time_json(value: Option<SystemTime>) -> Value {
    value
        .and_then(format_system_time)
        .map_or(Value::Null, Value::from)
}

fn denylist_policy_tier_label(tier: DenylistPolicyTier) -> &'static str {
    match tier {
        DenylistPolicyTier::Standard => "standard",
        DenylistPolicyTier::Emergency => "emergency",
        DenylistPolicyTier::Permanent => "permanent",
    }
}

fn cid_lookup_moderation_match_json(match_kind: &'static str, hit: &DenylistHit) -> Value {
    let entry = hit.entry();
    let scope = if entry.is_governance_backed() {
        "global"
    } else {
        "local"
    };

    json_object(vec![
        json_entry("scope", Value::from(scope)),
        json_entry("match_kind", Value::from(match_kind)),
        json_entry("pack_id", optional_str_json(entry.source_pack_id())),
        json_entry(
            "policy_tier",
            Value::from(denylist_policy_tier_label(entry.policy_tier())),
        ),
        json_entry("reason", optional_str_json(entry.reason())),
        json_entry("jurisdiction", optional_str_json(entry.jurisdiction())),
        json_entry("issued_at", optional_time_json(entry.issued_at())),
        json_entry("expires_at", optional_time_json(entry.expires_at())),
        json_entry("review_due_at", optional_time_json(entry.review_deadline())),
        json_entry(
            "issued_by_proposal_id",
            optional_str_json(entry.issued_by_proposal_id()),
        ),
        json_entry(
            "review_reference",
            optional_str_json(entry.review_reference()),
        ),
        json_entry(
            "governance_reference",
            optional_str_json(entry.governance_reference()),
        ),
        json_entry(
            "pack_manifest_cid",
            optional_str_json(entry.source_pack_manifest_cid()),
        ),
        json_entry(
            "merkle_root",
            optional_str_json(entry.source_pack_merkle_root()),
        ),
    ])
}

fn cid_lookup_moderation_json(state: &SharedAppState, stored: &StoredManifest) -> Value {
    let Some(denylist) = &state.sorafs_gateway_denylist else {
        return Value::Null;
    };

    let now = SystemTime::now();
    let mut has_local = false;
    let mut has_global = false;
    let mut matches = Vec::new();

    if let Some(hit) = denylist.check_manifest_digest(stored.manifest_digest(), now) {
        if hit.entry().is_governance_backed() {
            has_global = true;
        } else {
            has_local = true;
        }
        matches.push(cid_lookup_moderation_match_json("manifest_digest", &hit));
    }

    if let Some(hit) = denylist.check_cid(stored.manifest_cid(), now) {
        if hit.entry().is_governance_backed() {
            has_global = true;
        } else {
            has_local = true;
        }
        matches.push(cid_lookup_moderation_match_json("cid", &hit));
    }

    let status = if matches.is_empty() {
        "clear"
    } else if has_local && has_global {
        "mixed_blocked"
    } else if has_global {
        "global_blocked"
    } else {
        "local_blocked"
    };

    json_object(vec![
        json_entry("status", Value::from(status)),
        json_entry("public_links_enabled", Value::from(matches.is_empty())),
        json_entry("matches", Value::Array(matches)),
    ])
}

fn attach_cid_gateway_headers(response: &mut Response, stored: &StoredManifest) {
    response.headers_mut().insert(
        HeaderName::from_static(HEADER_SORA_CONTENT_CID),
        HeaderValue::from_str(&encode_content_cid(stored.manifest_cid()))
            .unwrap_or_else(|_| HeaderValue::from_static("invalid")),
    );
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("public, max-age=31536000, immutable"),
    );
}

fn should_use_spa_fallback_enabled(raw_path: &str, enabled: bool) -> bool {
    if !enabled {
        return false;
    }
    let trimmed = raw_path.trim_end_matches('/');
    let last = trimmed.rsplit('/').next().unwrap_or_default();
    !last.contains('.')
}

fn index_document_path(index_document: &str) -> Vec<String> {
    path_components_for_request(index_document, index_document)
        .unwrap_or_else(|| vec![index_document.to_owned()])
}

fn is_browser_document_request(headers: &HeaderMap) -> bool {
    if headers
        .get("sec-fetch-dest")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.eq_ignore_ascii_case("document"))
    {
        return true;
    }

    if headers
        .get("sec-fetch-mode")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.eq_ignore_ascii_case("navigate"))
    {
        return true;
    }

    headers
        .get(header::ACCEPT)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| {
            value.split(',').any(|entry| {
                let mime = entry.trim().split(';').next().unwrap_or_default().trim();
                mime.eq_ignore_ascii_case("text/html")
                    || mime.eq_ignore_ascii_case("application/xhtml+xml")
            })
        })
}

fn path_gateway_host_for_cid_suffix(suffix: &str) -> Option<String> {
    suffix
        .strip_prefix("sorafs.")
        .map(|value| value.trim().trim_end_matches('.').to_ascii_lowercase())
        .filter(|value| !value.is_empty())
}

fn canonical_cid_host_suffix_for_request(
    headers: &HeaderMap,
    config: &iroha_config::parameters::actual::SorafsGatewayUntrustedHosting,
) -> Option<String> {
    let host = headers.get(header::HOST)?.to_str().ok()?;
    let normalized_host = normalize_host_header(host)?;

    for suffix in [
        config.cid_host_suffixes.taira.as_str(),
        config.cid_host_suffixes.live.as_str(),
    ] {
        let Some(path_gateway_host) = path_gateway_host_for_cid_suffix(suffix) else {
            continue;
        };
        if normalized_host == path_gateway_host {
            return Some(suffix.to_owned());
        }
    }

    None
}

fn cid_gateway_request_path(uri: &Uri, cid: &str) -> Option<String> {
    let prefix = format!("/sorafs/cid/{cid}");
    let path = uri.path();
    if path == prefix || path == format!("{prefix}/") {
        return Some("/".to_owned());
    }

    path.strip_prefix(&format!("{prefix}/"))
        .map(|suffix| format!("/{suffix}"))
}

fn permanent_redirect(location: String) -> Response {
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::PERMANENT_REDIRECT;
    response.headers_mut().insert(
        header::LOCATION,
        HeaderValue::from_str(&location).unwrap_or_else(|_| HeaderValue::from_static("/")),
    );
    response
}

fn maybe_redirect_cid_gateway_request(
    state: &SharedAppState,
    headers: &HeaderMap,
    uri: &Uri,
    cid: &str,
) -> Option<Response> {
    let config = &state.sorafs_gateway_config.untrusted_hosting;
    if !config.enabled || !config.path_gateway_redirect {
        return None;
    }
    if config.redirect_html_only && !is_browser_document_request(headers) {
        return None;
    }

    let suffix = canonical_cid_host_suffix_for_request(headers, config)?;
    let path = cid_gateway_request_path(uri, cid)?;
    let mut location = format!("https://{cid}.{suffix}{path}");
    if let Some(query) = uri.query() {
        location.push('?');
        location.push_str(query);
    }
    Some(permanent_redirect(location))
}

fn build_site_file_response(
    state: &SharedAppState,
    stored: &StoredManifest,
    path: &[String],
) -> Response {
    let Some(file) = stored.file_by_path(path) else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let Ok(length) = usize::try_from(file.size) else {
        return json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "stored file exceeds supported response size",
        );
    };

    let bytes =
        match state
            .sorafs_node
            .read_payload_range(stored.manifest_id(), file.offset, length)
        {
            Ok(value) => value,
            Err(err) => return node_storage_error_response(err),
        };

    let mut response = Response::new(Body::from(bytes));
    *response.status_mut() = StatusCode::OK;
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static(content_type_for_path(path)),
    );
    response.headers_mut().insert(
        header::CONTENT_LENGTH,
        HeaderValue::from_str(&file.size.to_string())
            .unwrap_or_else(|_| HeaderValue::from_static("0")),
    );
    response
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_manifest(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match SiteFileListReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let resolved = match resolve_site_host(&state, &headers).await {
        Ok(value) => value,
        Err(response) => return response,
    };

    let manifest_bytes = match fs::read(resolved.stored.manifest_path()) {
        Ok(bytes) => bytes,
        Err(err) => {
            error!(
                ?err,
                "failed to read stored manifest bytes for site binding"
            );
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to read stored manifest bytes",
            );
        }
    };
    let (files, file_count, truncated_files) = bounded_file_listing_json(&resolved.stored, limit);
    let returned_file_count = files.len();

    let value = json_object(vec![
        json_entry("hostname", Value::from(resolved.hostname.clone())),
        json_entry(
            "content_cid",
            Value::from(encode_content_cid(resolved.stored.manifest_cid())),
        ),
        json_entry(
            "manifest_digest_hex",
            Value::from(hex::encode(resolved.stored.manifest_digest())),
        ),
        json_entry(
            "manifest_id_hex",
            Value::from(resolved.stored.manifest_id().to_owned()),
        ),
        json_entry(
            "manifest_b64",
            Value::from(BASE64_STANDARD.encode(manifest_bytes)),
        ),
        json_entry(
            "index_document",
            Value::from(resolved.index_document.clone()),
        ),
        json_entry("spa_fallback", Value::from(resolved.spa_fallback)),
        json_entry("file_count", Value::from(file_count as u64)),
        json_entry(
            "returned_file_count",
            Value::from(returned_file_count as u64),
        ),
        json_entry("limit", Value::from(limit as u64)),
        json_entry("truncated_files", Value::from(truncated_files)),
        json_entry("files", Value::Array(files)),
    ]);
    JsonBody(value).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_root(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
) -> Response {
    handle_get_sorafs_site_path(State(state), headers, Path(String::new())).await
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_path(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    Path(raw_path): Path<String>,
) -> Response {
    let resolved = match resolve_site_host(&state, &headers).await {
        Ok(value) => value,
        Err(response) => return response,
    };

    let Some(mut path) = path_components_for_request(&raw_path, &resolved.index_document) else {
        return StatusCode::NOT_FOUND.into_response();
    };

    if resolved.stored.file_by_path(&path).is_none()
        && should_use_spa_fallback_enabled(&raw_path, resolved.spa_fallback)
    {
        path = index_document_path(&resolved.index_document);
    }

    build_site_file_response(&state, &resolved.stored, &path)
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_lookup(
    State(state): State<SharedAppState>,
    Path(cid): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match SiteFileListReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let stored = match resolve_site_manifest_by_cid_unchecked(&state, &cid).await {
        Ok(value) => value,
        Err(response) => return response,
    };
    let (files, file_count, truncated_files) = bounded_file_listing_json(&stored, limit);
    let returned_file_count = files.len();

    let value = json_object(vec![
        json_entry(
            "content_cid",
            Value::from(encode_content_cid(stored.manifest_cid())),
        ),
        json_entry(
            "manifest_digest_hex",
            Value::from(hex::encode(stored.manifest_digest())),
        ),
        json_entry(
            "manifest_id_hex",
            Value::from(stored.manifest_id().to_owned()),
        ),
        json_entry(
            "index_document",
            stored
                .file_by_path(&["index.html".to_owned()])
                .map(|_| Value::from("index.html"))
                .unwrap_or(Value::Null),
        ),
        json_entry("file_count", Value::from(file_count as u64)),
        json_entry(
            "returned_file_count",
            Value::from(returned_file_count as u64),
        ),
        json_entry("limit", Value::from(limit as u64)),
        json_entry("truncated_files", Value::from(truncated_files)),
        json_entry("files", Value::Array(files)),
        json_entry("moderation", cid_lookup_moderation_json(&state, &stored)),
    ]);
    JsonBody(value).into_response()
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_root_redirect(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    uri: Uri,
    Path(cid): Path<String>,
) -> Response {
    if decode_content_cid(&cid).is_none() {
        return json_error(StatusCode::BAD_REQUEST, "invalid content CID");
    }

    if let Some(response) = maybe_redirect_cid_gateway_request(&state, &headers, &uri, &cid) {
        return response;
    }

    let mut location = format!("/sorafs/cid/{cid}/");
    if let Some(query) = uri.query() {
        location.push('?');
        location.push_str(query);
    }
    permanent_redirect(location)
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_root(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    uri: Uri,
    Path(cid): Path<String>,
) -> Response {
    handle_get_sorafs_cid_path(State(state), headers, uri, Path((cid, String::new()))).await
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_path(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    uri: Uri,
    Path((cid, raw_path)): Path<(String, String)>,
) -> Response {
    if decode_content_cid(&cid).is_none() {
        return json_error(StatusCode::BAD_REQUEST, "invalid content CID");
    }

    if let Some(response) = maybe_redirect_cid_gateway_request(&state, &headers, &uri, &cid) {
        return response;
    }

    let stored = match resolve_site_manifest_by_cid(&state, &cid).await {
        Ok(value) => value,
        Err(response) => return response,
    };

    let Some(path) = path_components_for_request(&raw_path, "index.html") else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let mut response = build_site_file_response(&state, &stored, &path);
    if response.status().is_success() {
        attach_cid_gateway_headers(&mut response, &stored);
    }
    response
}

#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_denylist_catalog(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match DenylistCatalogReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let Some(catalog) = &state.sorafs_gateway_denylist_catalog else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let opt_out_pack_count = catalog.opt_out_packs.len();
    let opt_out_packs = catalog
        .opt_out_packs
        .iter()
        .take(limit)
        .cloned()
        .map(Value::String)
        .collect::<Vec<_>>();
    let extra_pack_count = catalog.extra_packs.len();
    let extra_packs = catalog
        .extra_packs
        .iter()
        .take(limit)
        .cloned()
        .map(Value::String)
        .collect::<Vec<_>>();
    let pack_count = catalog.packs.len();
    let packs = catalog
        .packs
        .iter()
        .take(limit)
        .map(|pack| {
            json_object(vec![
                json_entry("pack_id", Value::from(pack.pack_id.clone())),
                json_entry(
                    "version",
                    pack.version
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry("default_enabled", Value::from(pack.default_enabled)),
                json_entry("active", Value::from(pack.active)),
                json_entry(
                    "policy_tier",
                    pack.policy_tier
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "manifest_cid",
                    pack.manifest_cid
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "merkle_root",
                    pack.merkle_root
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "issued_by_proposal_id",
                    pack.issued_by_proposal_id
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "review_reference",
                    pack.review_reference
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "jurisdiction",
                    pack.jurisdiction
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "issued_at",
                    pack.issued_at
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry(
                    "expires_at",
                    pack.expires_at
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
                json_entry("entry_count", Value::from(pack.entry_count as u64)),
            ])
        })
        .collect::<Vec<_>>();

    let value = json_object(vec![
        json_entry("version", Value::from(catalog.version as u64)),
        json_entry(
            "jurisdiction",
            catalog
                .jurisdiction
                .clone()
                .map(Value::String)
                .unwrap_or(Value::Null),
        ),
        json_entry("limit", Value::from(limit as u64)),
        json_entry("opt_out_pack_count", Value::from(opt_out_pack_count as u64)),
        json_entry(
            "returned_opt_out_pack_count",
            Value::from(opt_out_packs.len() as u64),
        ),
        json_entry(
            "truncated_opt_out_packs",
            Value::from(opt_out_pack_count > limit),
        ),
        json_entry("opt_out_packs", Value::Array(opt_out_packs)),
        json_entry("extra_pack_count", Value::from(extra_pack_count as u64)),
        json_entry(
            "returned_extra_pack_count",
            Value::from(extra_packs.len() as u64),
        ),
        json_entry(
            "truncated_extra_packs",
            Value::from(extra_pack_count > limit),
        ),
        json_entry("extra_packs", Value::Array(extra_packs)),
        json_entry("pack_count", Value::from(pack_count as u64)),
        json_entry("returned_pack_count", Value::from(packs.len() as u64)),
        json_entry("truncated_packs", Value::from(pack_count > limit)),
        json_entry("packs", Value::Array(packs)),
    ]);

    JsonBody(value).into_response()
}

