    fn decode_hex_32_decodes_expected_bytes() {
        let hex = hex::encode([0xAA; 32]);
        let decoded = decode_hex_32(&hex).expect("decode succeeds");
        assert_eq!(decoded, [0xAA; 32]);
    }
