    async fn seed_moderation_quarantine_for_payload(
        app: SharedAppState,
        signer: &OrderbookAccountFixture,
        subject: &str,
        payload: &[u8],
        screened_at_unix: u64,
    ) -> String {
        let subject_digest_hex = hex::encode(blake3::hash(payload).as_bytes());
        let response = post_moderation_screening_result(
            app,
            signer,
            moderation_screening_result_body_with_subject_digest(
                subject,
                subject_digest_hex,
                0x57,
                0x67,
                7_500,
                "quarantine",
                screened_at_unix,
            ),
        )
        .await;
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect screening body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode screening body");
        value
            .get("quarantine")
            .and_then(|record| record.get("quarantine_id_hex"))
            .and_then(Value::as_str)
            .expect("quarantine id")
            .to_owned()
    }

    #[test]
    fn orderbook_api_error_ratio_tracks_route_outcomes() {
        const ROUTE: &str = "/test/sorafs/orderbook/error-ratio";
        reset_orderbook_api_outcome_for_test(ROUTE);

        assert_eq!(record_orderbook_api_outcome(ROUTE, false), 0.0);
        assert_eq!(record_orderbook_api_outcome(ROUTE, true), 0.5);
        let ratio = record_orderbook_api_outcome(ROUTE, true);
        assert!((ratio - (2.0 / 3.0)).abs() < f64::EPSILON);
    }

